//! Deterministic navigation indexes generated from executable sources.
//!
//! This module owns generation only: `cargo run -p xtask -- architecture`
//! writes `docs/generated/` from Cargo metadata, the WIT/command/event
//! contract sources, and the harness scenario/profile catalog. Generated files
//! never own semantics; `--check` fails when they are stale without mutating.
//!
//! Staleness is keyed on a deterministic fingerprint of the generator inputs,
//! never on a commit id or wall clock, so a fresh checkout without local
//! changes produces byte-identical output.

use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;

const CRATE_GRAPH_FILE: &str = "docs/generated/crate-graph.md";
const CONTRACT_INDEX_FILE: &str = "docs/generated/contract-index.md";
const SCENARIO_INDEX_FILE: &str = "docs/generated/scenario-index.md";

const WIT_DIR: &str = "crates/mc-script/wit";

// Sibling checkouts are external to the core map. These names are
// documentation-only: local presence is reported on stdout and never baked
// into the compared artifact, so a fresh core checkout without siblings
// produces byte-identical output.
const SIBLING_REPOS: &[&str] = &["solaris-default-plugins", "solaris-loader"];

pub(super) fn run_architecture(check: bool) -> Result<(), i32> {
    let root = workspace_root().map_err(|err| {
        eprintln!("architecture: {err}");
        2
    })?;
    let generated = architecture_documents(&root).map_err(|err| {
        eprintln!("architecture: {err}");
        2
    })?;
    let mut stale = Vec::new();
    for (relative, contents) in &generated {
        let path = root.join(relative);
        match fs::read_to_string(&path) {
            Ok(current) if current == *contents => {}
            Ok(_) => stale.push(relative.clone()),
            Err(_) => stale.push(relative.clone()),
        }
    }
    if check {
        if stale.is_empty() {
            println!("architecture: 3 files current");
            report_sibling_availability(&root);
            return Ok(());
        }
        for relative in &stale {
            println!("STALE: {relative}");
        }
        eprintln!(
            "architecture: {} stale file(s); rerun without --check",
            stale.len()
        );
        return Err(1);
    }
    for (relative, contents) in &generated {
        let path = root.join(relative);
        if let Some(parent) = path.parent()
            && let Err(err) = fs::create_dir_all(parent)
        {
            eprintln!("architecture: cannot create {}: {err}", parent.display());
            return Err(2);
        }
        if let Err(err) = fs::write(&path, contents) {
            eprintln!("architecture: cannot write {}: {err}", path.display());
            return Err(2);
        }
    }
    println!("architecture: 3 files generated");
    report_sibling_availability(&root);
    Ok(())
}

fn report_sibling_availability(root: &Path) {
    for sibling in SIBLING_REPOS {
        let status = if root.join("..").join(sibling).is_dir() {
            "present (local only, not part of compared artifact)"
        } else {
            "unavailable"
        };
        println!("sibling {sibling}: {status}");
    }
}

fn workspace_root() -> Result<PathBuf, String> {
    let mut dir = std::env::current_dir().map_err(|err| format!("current_dir failed: {err}"))?;
    loop {
        if dir.join("Cargo.toml").is_file() && dir.join("crates").is_dir() {
            return Ok(dir);
        }
        if !dir.pop() {
            return Err("could not find workspace root with Cargo.toml and crates/".into());
        }
    }
}

fn source_fingerprint(bodies: &[&str]) -> String {
    // FNV-1a 64 over the generated bodies (which are pure functions of the
    // executable inputs). Any input change alters a body and therefore the
    // fingerprint; `--check` compares full files so staleness is detected
    // without a commit id or wall clock.
    let mut state: u64 = 0xcbf29ce484222325;
    for body in bodies {
        for byte in body.bytes() {
            state ^= u64::from(byte);
            state = state.wrapping_mul(0x100000001b3);
        }
        state ^= 0xff;
        state = state.wrapping_mul(0x100000001b3);
    }
    format!("{state:016x}")
}

fn with_header(body: &str, fingerprint: &str) -> String {
    let mut parts = body.splitn(2, "\n\n");
    let title = parts.next().unwrap_or("");
    let rest = parts.next().unwrap_or("");
    let mut out = String::new();
    out.push_str(title);
    out.push_str("\n\n<!-- GENERATED BY `cargo run -p xtask -- architecture`. DO NOT EDIT. -->\n");
    out.push_str(&format!("<!-- source fingerprint: {fingerprint} -->\n\n"));
    out.push_str(rest);
    out
}

fn architecture_documents(root: &Path) -> Result<Vec<(String, String)>, String> {
    let graph_body = crate_graph_document(root)?;
    let contract_body = contract_index_document(root)?;
    let scenario_body = scenario_index_document(root)?;
    let fingerprint = source_fingerprint(&[&graph_body, &contract_body, &scenario_body]);
    Ok(vec![
        (
            CRATE_GRAPH_FILE.to_owned(),
            with_header(&graph_body, &fingerprint),
        ),
        (
            CONTRACT_INDEX_FILE.to_owned(),
            with_header(&contract_body, &fingerprint),
        ),
        (
            SCENARIO_INDEX_FILE.to_owned(),
            with_header(&scenario_body, &fingerprint),
        ),
    ])
}

fn crate_graph_document(root: &Path) -> Result<String, String> {
    let metadata = cargo_metadata(root)?;
    let ids: BTreeMap<&str, &str> = metadata
        .packages
        .iter()
        .map(|package| (package.id.as_str(), package.name.as_str()))
        .collect();
    // Workspace membership is the executable source: a new crate enters the
    // map through `cargo metadata`, never through a hand-kept list.
    let mut member_names = BTreeSet::new();
    for member in &metadata.workspace_members {
        let Some(name) = ids.get(member.as_str()) else {
            return Err(format!(
                "cargo metadata: workspace member {member} has no package entry"
            ));
        };
        member_names.insert((*name).to_owned());
    }
    if member_names.is_empty() {
        return Err("cargo metadata: no workspace members".into());
    }
    let member_ids: BTreeSet<&str> = metadata
        .workspace_members
        .iter()
        .map(String::as_str)
        .collect();
    let resolve: BTreeMap<&str, &[String]> = metadata
        .nodes
        .iter()
        .map(|node| (node.id.as_str(), node.deps.as_slice()))
        .collect();
    let mut edges = BTreeMap::<String, BTreeSet<String>>::new();
    for member in &metadata.workspace_members {
        let name = ids
            .get(member.as_str())
            .expect("workspace member package entry checked above");
        let Some(deps) = resolve.get(member.as_str()) else {
            return Err(format!(
                "cargo metadata: workspace member {member} has no resolve node"
            ));
        };
        let mut direct = BTreeSet::new();
        for dependency in deps.iter() {
            if !member_ids.contains(dependency.as_str()) {
                continue;
            }
            if let Some(target) = ids.get(dependency.as_str())
                && *target != *name
            {
                direct.insert((*target).to_owned());
            }
        }
        edges.insert((*name).to_owned(), direct);
    }
    let mut out = String::new();
    out.push_str("# Crate dependency graph\n\n");
    out.push_str("Core workspace crates and their direct intra-workspace dependencies.\n");
    out.push_str("Workspace membership comes from `cargo metadata`; sibling checkouts\n");
    out.push_str("are external and never graph edges.\n\n");
    out.push_str("```text\n");
    for name in &member_names {
        let empty = BTreeSet::new();
        let direct = edges.get(name).unwrap_or(&empty);
        if direct.is_empty() {
            out.push_str(&format!("{name} -> (none)\n"));
        } else {
            out.push_str(&format!(
                "{name} -> {}\n",
                direct.iter().cloned().collect::<Vec<_>>().join(", ")
            ));
        }
    }
    out.push_str("```\n\n");
    out.push_str("## Sibling availability\n\n");
    out.push_str("Sibling checkouts are external to the core map; local presence is\n");
    out.push_str("reported on stdout only and never baked into this file.\n\n");
    for sibling in SIBLING_REPOS {
        out.push_str(&format!("- {sibling}: external\n"));
    }
    out.push_str(
        "\nGenerated artifacts never own semantics; see the owning manifests and ADR 0006.\n",
    );
    Ok(out)
}

struct CargoMetadata {
    packages: Vec<CargoPackage>,
    workspace_members: Vec<String>,
    nodes: Vec<CargoNode>,
}

struct CargoPackage {
    id: String,
    name: String,
}

struct CargoNode {
    id: String,
    deps: Vec<String>,
}

fn cargo_metadata(root: &Path) -> Result<CargoMetadata, String> {
    // Full metadata carries `resolve.nodes[].deps[].pkg`, which `--no-deps`
    // omits. Only workspace members enter the graph; external dependencies
    // never do.
    let output = Command::new("cargo")
        .arg("metadata")
        .arg("--format-version")
        .arg("1")
        .current_dir(root)
        .output()
        .map_err(|err| format!("cargo metadata failed: {err}"))?;
    if !output.status.success() {
        return Err("cargo metadata exited nonzero".into());
    }
    let text = String::from_utf8_lossy(&output.stdout).into_owned();
    parse_cargo_metadata(&text)
}

fn parse_cargo_metadata(text: &str) -> Result<CargoMetadata, String> {
    let value: serde_json::Value =
        serde_json::from_str(text).map_err(|err| format!("cargo metadata is not JSON: {err}"))?;
    let mut packages = Vec::new();
    let package_list = value
        .get("packages")
        .and_then(|packages| packages.as_array())
        .ok_or_else(|| "cargo metadata has no packages".to_owned())?;
    for package in package_list {
        let id = package
            .get("id")
            .and_then(|id| id.as_str())
            .unwrap_or_default();
        let name = package
            .get("name")
            .and_then(|name| name.as_str())
            .unwrap_or_default();
        if !id.is_empty() && !name.is_empty() {
            packages.push(CargoPackage {
                id: id.to_owned(),
                name: name.to_owned(),
            });
        }
    }
    let mut workspace_members = Vec::new();
    let member_list = value
        .get("workspace_members")
        .and_then(|members| members.as_array())
        .ok_or_else(|| "cargo metadata has no workspace_members".to_owned())?;
    for member in member_list {
        if let Some(id) = member.as_str() {
            workspace_members.push(id.to_owned());
        }
    }
    let mut nodes = Vec::new();
    let node_list = value
        .pointer("/resolve/nodes")
        .and_then(|nodes| nodes.as_array())
        .ok_or_else(|| "cargo metadata has no resolve nodes".to_owned())?;
    for node in node_list {
        let id = node
            .get("id")
            .and_then(|id| id.as_str())
            .unwrap_or_default();
        if id.is_empty() {
            continue;
        }
        let mut deps = Vec::new();
        if let Some(dep_list) = node.get("deps").and_then(|deps| deps.as_array()) {
            for dep in dep_list {
                if let Some(pkg) = dep.get("pkg").and_then(|pkg| pkg.as_str()) {
                    deps.push(pkg.to_owned());
                }
            }
        }
        nodes.push(CargoNode {
            id: id.to_owned(),
            deps,
        });
    }
    Ok(CargoMetadata {
        packages,
        workspace_members,
        nodes,
    })
}

fn contract_index_document(root: &Path) -> Result<String, String> {
    // The WIT file set is the executable source: every `*.wit` in the
    // contract directory enters the index in sorted order.
    let mut files: Vec<String> = Vec::new();
    let entries =
        fs::read_dir(root.join(WIT_DIR)).map_err(|err| format!("cannot list {WIT_DIR}: {err}"))?;
    for entry in entries {
        let entry = entry.map_err(|err| format!("cannot list {WIT_DIR}: {err}"))?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.ends_with(".wit") {
            files.push(name);
        }
    }
    files.sort();
    if files.is_empty() {
        return Err(format!("missing WIT contract sources in {WIT_DIR}"));
    }
    let mut groups: BTreeMap<String, Vec<ContractItem>> = BTreeMap::new();
    for file in &files {
        let path = root.join(WIT_DIR).join(file);
        let source = fs::read_to_string(&path)
            .map_err(|_| format!("missing WIT contract source: {WIT_DIR}/{file}"))?;
        for item in wit_items(&source, file) {
            groups.entry(item.group.clone()).or_default().push(item);
        }
    }
    append_rust_contract_items(root, &mut groups)?;
    for items in groups.values_mut() {
        items.sort();
        items.dedup();
    }
    let mut out = String::new();
    out.push_str("# Contract index\n\n");
    out.push_str("Grouped public WIT/command/event contract names with source links.\n");
    out.push_str("Semantics live in the linked sources and the owning ADR, never here.\n\n");
    for (group, items) in &groups {
        out.push_str(&format!("## {group}\n\n"));
        for item in items {
            out.push_str(&format!(
                "- `{}` ([source](../../{}))\n",
                item.name, item.source
            ));
        }
        out.push('\n');
    }
    Ok(out)
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
struct ContractItem {
    group: String,
    name: String,
    source: String,
}

fn wit_items(source: &str, file: &str) -> Vec<ContractItem> {
    let mut items = Vec::new();
    let mut current_group = String::from("wit");
    for line in source.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("interface ") {
            current_group = rest
                .split_whitespace()
                .next()
                .unwrap_or("wit")
                .trim_end_matches('{')
                .trim()
                .to_owned();
            continue;
        }
        if trimmed.starts_with("//") {
            continue;
        }
        // Public WIT functions: `name: func(...)`. Without this the index
        // would silently drop callback/entrypoint removals.
        if let Some((name, rest)) = trimmed.split_once(':') {
            let rest = rest.trim_start();
            if rest.starts_with("func(") || rest.starts_with("func<") {
                let name = name.trim();
                if !name.is_empty()
                    && name
                        .chars()
                        .all(|next| next.is_ascii_alphanumeric() || next == '-' || next == '_')
                {
                    items.push(ContractItem {
                        group: format!("wit:{current_group}"),
                        name: name.to_owned(),
                        source: format!("{WIT_DIR}/{file}"),
                    });
                    continue;
                }
            }
        }
        for prefix in [
            "record ",
            "variant ",
            "enum ",
            "flags ",
            "type ",
            "resource ",
        ] {
            if let Some(rest) = trimmed.strip_prefix(prefix) {
                let name: String = rest
                    .chars()
                    .take_while(|next| next.is_ascii_alphanumeric() || *next == '-' || *next == '_')
                    .collect();
                if !name.is_empty() {
                    items.push(ContractItem {
                        group: format!("wit:{current_group}"),
                        name,
                        source: format!("{WIT_DIR}/{file}"),
                    });
                }
                break;
            }
        }
    }
    items
}

fn append_rust_contract_items(
    root: &Path,
    groups: &mut BTreeMap<String, Vec<ContractItem>>,
) -> Result<(), String> {
    let path = root.join("crates/mc-script/src/lib.rs");
    let source = fs::read_to_string(&path)
        .map_err(|_| "missing Rust contract source: crates/mc-script/src/lib.rs".to_owned())?;
    let commands = rust_enum_variants(&source, "pub enum ScriptCommand");
    if commands.is_empty() {
        return Err(
            "missing Rust contract source: `pub enum ScriptCommand` has no variants".to_owned(),
        );
    }
    for variant in commands {
        groups
            .entry("rust:ScriptCommand".to_owned())
            .or_default()
            .push(ContractItem {
                group: "rust:ScriptCommand".to_owned(),
                name: variant,
                source: "crates/mc-script/src/lib.rs".to_owned(),
            });
    }
    let events = rust_enum_variants(&source, "pub enum ScriptEventKind");
    if events.is_empty() {
        return Err(
            "missing Rust contract source: `pub enum ScriptEventKind` has no variants".to_owned(),
        );
    }
    for variant in events {
        groups
            .entry("rust:ScriptEventKind".to_owned())
            .or_default()
            .push(ContractItem {
                group: "rust:ScriptEventKind".to_owned(),
                name: variant,
                source: "crates/mc-script/src/lib.rs".to_owned(),
            });
    }
    Ok(())
}

fn rust_enum_variants(source: &str, declaration: &str) -> Vec<String> {
    let Some(start) = find_enum_declaration(source, declaration) else {
        return Vec::new();
    };
    let rest = &source[start..];
    let Some(body_start) = rest.find('{') else {
        return Vec::new();
    };
    let body = &rest[body_start..];
    let mut variants = Vec::new();
    let mut depth = 0usize;
    for line in body.lines().skip(1) {
        let trimmed = line.trim();
        if depth == 0 {
            if trimmed.starts_with("///") || trimmed.starts_with("//!") || trimmed.is_empty() {
                continue;
            }
            if trimmed.starts_with("#[") {
                continue;
            }
            let mut name = String::new();
            for next in trimmed.chars() {
                if next.is_ascii_alphanumeric() || next == '_' {
                    name.push(next);
                } else {
                    break;
                }
            }
            if !name.is_empty() && name.chars().next().is_some_and(|next| next.is_uppercase()) {
                variants.push(name);
            }
            if trimmed == "}" {
                return variants;
            }
        }
        for byte in line.bytes() {
            if byte == b'{' {
                depth += 1;
            } else if byte == b'}' {
                if depth == 0 {
                    return variants;
                }
                depth -= 1;
            }
        }
    }
    variants
}

fn find_enum_declaration(source: &str, declaration: &str) -> Option<usize> {
    // `str::find` alone also matches longer identifiers
    // (`ScriptCommandSubmissionError` contains `ScriptCommand`). Only accept
    // the declaration when the next character ends the identifier.
    let mut search = 0;
    while let Some(relative) = source[search..].find(declaration) {
        let start = search + relative;
        let end = start + declaration.len();
        let boundary = source[end..]
            .chars()
            .next()
            .is_none_or(|next| next.is_whitespace() || next == '{');
        if boundary {
            return Some(start);
        }
        search = end;
    }
    None
}

fn scenario_index_document(root: &Path) -> Result<String, String> {
    let output = Command::new("python3")
        .arg("-m")
        .arg("tools.harness")
        .arg("list")
        .current_dir(root)
        .output()
        .map_err(|err| format!("harness list failed: {err}"))?;
    if !output.status.success() {
        return Err("harness list exited nonzero".into());
    }
    let profiles = String::from_utf8_lossy(&output.stdout).into_owned();
    let output = Command::new("python3")
        .arg("-m")
        .arg("tools.harness")
        .arg("explain")
        .current_dir(root)
        .output()
        .map_err(|err| format!("harness explain failed: {err}"))?;
    if !output.status.success() {
        return Err("harness explain exited nonzero".into());
    }
    let scenarios = String::from_utf8_lossy(&output.stdout).into_owned();
    let mut out = String::new();
    out.push_str("# Scenario and profile index\n\n");
    out.push_str("Executable `tools/harness` profiles and catalog scenarios.\n");
    out.push_str("Resolution and evidence stay in the catalog; this file is navigation only.\n\n");
    out.push_str("## Profiles\n\n```text\n");
    out.push_str(profiles.trim());
    out.push_str("\n```\n\n## Scenarios\n\n```text\n");
    out.push_str(scenarios.trim());
    out.push_str("\n```\n");
    Ok(out)
}
